const root = document.querySelector('#root');
const copy = {
 en: {name:'The Thoughtful Life',tag:'A PERSONAL JOURNAL',nav:'The journal',about:'Our intention',add:'Write a reflection',eyebrow:'THINK DEEPLY. LIVE WELL.',title:'A little wisdom.<br>A healthier everyday.',intro:'Notes on philosophy, small habits, and the art of living well. A space to learn, reflect, and grow together.',browse:'Explore the journal',quote:'“The happiness of your life depends upon the quality of your thoughts.”',author:'— Marcus Aurelius, Meditations',latest:'From the journal',sub:'Ideas to sit with. Small things to try.',all:'All reflections',philosophy:'Philosophy',health:'Healthy living',personal:'My reflections',read:'Read reflection',empty:'No reflections here yet. Your next idea could be the first.',intent:'A considered life, one day at a time.',intentText:'This journal brings together timeless questions and practical everyday choices. You don’t need all the answers. Start with curiosity, a little kindness, and one small step.',note:'Health notes offer general educational ideas, not personalised medical advice. Adapt activities to your needs and seek professional advice when needed.',close:'Close',editor:'Make room for your own ideas',editorSub:'A thought worth keeping, a habit worth sharing.',titleLabel:'Title',bodyLabel:'Your reflection',category:'Category',language:'Language of your post',save:'Save reflection',local:'Your posts are saved in this browser only. Export a backup to keep them safe or move them to another device. They are not published to other visitors.',export:'Export my posts',import:'Import a backup',remove:'Delete',confirm:'Delete this reflection?',saved:'Reflection saved.',error:'Could not save. Browser storage may be unavailable or full.',invalid:'This backup is invalid. Please choose an exported journal JSON file.',imported:'Backup imported.',footer:'A quieter corner of the internet.',count:'reflections',readTime:'3 min read',back:'Back to journal'},
 yue:{name:'好好生活',tag:'個人思考札記',nav:'生活札記',about:'我哋嘅初心',add:'寫低一個想法',eyebrow:'諗深啲・活好啲',title:'多一點智慧。<br>每日過得健康啲。',intro:'分享哲學嘅啟發、日常小習慣，同好好生活嘅心得。一齊學習、反思，慢慢成長。',browse:'睇吓生活札記',quote:'「你嘅生活快唔快樂，取決於你思想嘅質素。」',author:'— 馬可・奧理略《沉思錄》（意譯）',latest:'最新札記',sub:'有啲想法，值得停低諗吓；有啲小事，值得試吓。',all:'全部札記',philosophy:'哲學思考',health:'健康生活',personal:'我嘅札記',read:'閱讀札記',empty:'呢度仲未有札記。不如寫低你第一個想法。',intent:'用心生活，由今日開始。',intentText:'呢度將哲學問題同日常選擇連埋一齊。唔使急住搵齊答案，帶住好奇心、善意，同一個小小嘅行動開始就得。',note:'健康札記只係一般教育資訊，唔係個人醫療建議。請按自己情況調整，有需要就問專業人士。',close:'關閉',editor:'留個位畀你嘅想法',editorSub:'寫低值得記住嘅思考，分享值得試嘅習慣。',titleLabel:'標題',bodyLabel:'你嘅札記',category:'分類',language:'札記語言',save:'儲存札記',local:'你嘅札記只會儲存喺呢個瀏覽器。記得匯出備份，方便保存或者搬去另一部裝置。其他訪客睇唔到你嘅札記。',export:'匯出我嘅札記',import:'匯入備份',remove:'刪除',confirm:'要刪除呢篇札記？',saved:'札記儲存咗。',error:'儲存唔到。瀏覽器儲存空間可能用唔到或者已經滿咗。',invalid:'備份格式唔啱。請揀返匯出嘅札記 JSON 檔案。',imported:'備份匯入咗。',footer:'喺網絡留一個安靜角落。',count:'篇札記',readTime:'約 3 分鐘',back:'返去札記'},
 zh:{name:'好好生活',tag:'个人思考札记',nav:'生活札记',about:'我们的初心',add:'写一篇札记',eyebrow:'深入思考・健康生活',title:'多一点智慧。<br>让每一天更健康。',intro:'分享哲学的启发、日常小习惯与认真生活的心得。一起学习、反思，慢慢成长。',browse:'探索生活札记',quote:'“你生活的幸福取决于你思想的质量。”',author:'— 马可·奥勒留《沉思录》（意译）',latest:'最新札记',sub:'值得思考的想法，值得尝试的小事。',all:'全部札记',philosophy:'哲学思考',health:'健康生活',personal:'我的札记',read:'阅读札记',empty:'这里还没有札记。写下你的第一个想法吧。',intent:'用心生活，从今天开始。',intentText:'这里将哲学问题与日常选择联系起来。不必急于找到所有答案，带着好奇心、善意和一个小小的行动开始。',note:'健康札记仅提供一般教育信息，不是个人医疗建议。请根据自身情况调整，必要时咨询专业人士。',close:'关闭',editor:'给自己的想法留一点空间',editorSub:'写下值得记住的思考，分享值得尝试的习惯。',titleLabel:'标题',bodyLabel:'你的札记',category:'分类',language:'札记语言',save:'保存札记',local:'你的札记仅保存在当前浏览器中。请导出备份，以便保存或转移到其他设备。其他访客看不到这些札记。',export:'导出我的札记',import:'导入备份',remove:'删除',confirm:'删除这篇札记？',saved:'札记已保存。',error:'无法保存，浏览器存储可能不可用或已满。',invalid:'备份格式无效。请选择导出的札记 JSON 文件。',imported:'备份已导入。',footer:'互联网中的一个安静角落。',count:'篇札记',readTime:'约 3 分钟',back:'返回札记'}
};
const examples = [
 ['control','philosophy','01', ['What is actually in your control?','有啲嘢，唔使樣樣都控制','哪些事情真正由你掌控？'], ['A Stoic practice for meeting an uncertain day with a steadier mind.','用斯多噶哲學嘅小練習，安定咁面對未知嘅一天。','用斯多葛哲学的小练习，更从容地面对不确定的一天。'], ['The Stoic philosopher Epictetus distinguishes our judgements and choices from things beyond our control. This is not an invitation to stop caring. It is a way to put effort where it can help.\n\nTry this: write down a worry. Divide it into “my next action” and “what I cannot decide.” You cannot guarantee how another person responds, but you can choose a clear, kind message.\n\nToday’s question: what is one useful action I can take, without demanding a particular outcome?','哲學家愛比克泰德提醒我哋，自己嘅判斷同選擇，同控制唔到嘅事係兩回事。唔係叫你唔理，而係將心力放喺幫得上忙嘅地方。\n\n試吓寫低一件擔心嘅事，分成「我下一步可以做乜」同「我決定唔到嘅事」。你保證唔到對方點回應，但可以選擇清楚、友善咁表達。\n\n今日問吓自己：唔要求一定有某個結果，我可以做邊一個有用嘅行動？','哲学家爱比克泰德区分了我们的判断与选择，以及无法控制的事情。这不是让我们漠不关心，而是把努力放在能发挥作用的地方。\n\n试着写下一件担忧，分成“我的下一步行动”和“我无法决定的事”。你无法保证别人的回应，却可以选择清楚、友善地表达。\n\n今天的问题：不强求特定结果，我能采取什么有用的行动？']],
 ['walk','health','02',['The quiet power of a daily walk','每日行一陣，慢慢有改變','每天走一走，小步带来改变'],['Make movement a gentle invitation, rather than another task to perfect.','唔使做到完美，輕鬆邀請自己郁一郁。','不必追求完美，温柔地邀请自己动起来。'],['Regular movement can support physical and mental wellbeing. Walking is one accessible option, and a short walk is a reasonable place to start if it suits your abilities.\n\nTry five or ten comfortable minutes after lunch. Notice the light, your breathing, and the world around you. Increase gradually if you feel comfortable; choose seated or other adapted movement if that works better for you.\n\nThe goal is a repeatable habit, not a speed or step-count competition. Stop if you feel pain, dizziness or unusual breathlessness, and seek advice if needed.','經常活動身體有助身心健康。行路係其中一個選擇，如果適合你嘅能力，可以由短短一段開始。\n\n試吓食完午餐，舒服咁行五至十分鐘。留意光線、呼吸，同身邊嘅環境。覺得舒服先慢慢加；如果坐住做運動或者其他活動更適合你，都一樣可以。\n\n目標係建立持續到嘅習慣，唔係鬥快或者鬥步數。覺得痛、暈或者異常氣促，就停低，有需要時尋求專業意見。','规律活动有助于身心健康。散步是一种选择，如果适合你的身体能力，可以从短时间开始。\n\n试着午餐后舒适地走五到十分钟，留意光线、呼吸和周围环境。感觉舒适再逐渐增加；坐姿运动或其他适应性活动也可以。\n\n目标是建立可以持续的习惯，而不是比速度或步数。出现疼痛、头晕或异常气短时应停止，必要时寻求专业意见。']],
 ['beginner','philosophy','03',['Leave room to be a beginner','畀自己做初學者嘅空間','给自己做初学者的空间'],['Curiosity begins when we loosen our need to have every answer.','唔急住樣樣都有答案，好奇心先有空間。','不急着拥有所有答案，好奇心才有空间。'],['Socratic questioning asks us to examine what we think we know. A useful conversation can begin with “What do you mean?” rather than “You are wrong.”\n\nChoose one belief you hold strongly. Ask: what experience shaped it? What evidence might change my mind? Could a thoughtful person see this differently?\n\nBeing open does not mean accepting every claim. It means listening carefully, checking reasons, and allowing yourself to learn.','蘇格拉底式提問，鼓勵我哋檢視以為自己知道嘅事。一段有用嘅對話，可以由「你係咩意思？」開始，唔一定要先講「你錯喇」。\n\n揀一個你深信嘅想法。問吓：係咩經驗令我咁諗？有咩證據會令我改變睇法？一個認真思考嘅人，會唔會有另一個角度？\n\n開放唔等於乜都信，而係用心聽、查清理由，同容許自己學習。','苏格拉底式提问鼓励我们检视自以为知道的事情。一段有价值的对话，可以从“你指的是什么？”开始，而不是“你错了”。\n\n选择一个你坚信的观点：什么经历塑造了它？什么证据可能让你改变想法？一个认真思考的人会不会有另一种视角？\n\n开放不等于相信所有说法，而是认真倾听、核查理由，并允许自己学习。']],
 ['sleep','health','04',['Give your evening a softer landing','畀夜晚一個溫柔嘅收尾','让夜晚温柔地收尾'],['A small wind-down ritual can help you make space for rest.','用一個小小嘅睡前習慣，留返空間休息。','用一个小小的睡前习惯，为休息留出空间。'],['Sleep needs vary, but regular sleep and wake times can help support a healthy routine. A peaceful evening is not a guarantee of perfect sleep; it is a way to give rest a chance.\n\nTry a ten-minute transition: dim the lights, put tomorrow’s essentials aside, and read a few pages or breathe quietly. Keep late caffeine in mind if it affects your sleep.\n\nIf sleep problems persist or affect daily life, speak with a healthcare professional rather than blaming yourself.','每個人嘅睡眠需要唔同，但固定啲嘅作息時間，有助建立健康習慣。安靜嘅夜晚唔保證一定瞓得好，只係畀休息多一個機會。\n\n試吓用十分鐘收尾：調暗燈光、準備聽日嘅用品，再睇幾頁書或者安靜呼吸。如果咖啡因影響你瞓覺，就留意夜晚嘅攝取。\n\n如果長期瞓唔好，或者影響日常生活，搵醫護人員傾吓，唔好怪自己。','每个人的睡眠需求不同，但相对规律的作息有助于建立健康习惯。安静的夜晚不保证完美睡眠，只是给休息一个机会。\n\n试试十分钟的睡前过渡：调暗灯光，准备好明天的用品，然后读几页书或安静呼吸。如果咖啡因影响睡眠，请留意晚间摄入。\n\n如果睡眠问题持续或影响日常生活，请咨询医护人员，不必责怪自己。']]
];
let lang = 'en', filter = 'all', posts = [], storageWarning = false;
try { lang = localStorage.getItem('thoughtful-language') || 'en'; posts = JSON.parse(localStorage.getItem('thoughtful-posts') || '[]'); if (!validPosts(posts)) posts = []; } catch { storageWarning = true; }
if (!copy[lang]) lang = 'en';
function validPosts(value) { return Array.isArray(value) && value.length <= 500 && value.every(p => p && typeof p.id === 'string' && typeof p.title === 'string' && p.title.length <= 140 && typeof p.body === 'string' && p.body.length <= 20000 && ['en','yue','zh'].includes(p.lang) && ['philosophy','health'].includes(p.category)); }
function esc(s) { return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function currentPosts() { const i = ['en','yue','zh'].indexOf(lang); return [...posts.filter(p => p.lang === lang).map(p => ({...p, own:true, summary:p.body.slice(0,110)})), ...examples.map(p => ({id:p[0], category:p[1], number:p[2], title:p[3][i],summary:p[4][i],body:p[5][i]}))]; }
function persist(next) { try { localStorage.setItem('thoughtful-posts', JSON.stringify(next)); posts = next; return true; } catch { alert(copy[lang].error); return false; } }
function render() {
 const t = copy[lang]; document.documentElement.lang = lang === 'zh' ? 'zh-Hans' : lang === 'yue' ? 'yue-Hant' : 'en'; document.title = t.name;
 const visible = currentPosts().filter(p => filter === 'all' || (filter === 'personal' ? p.own : p.category === filter));
 root.innerHTML = `<header><a class="brand" href="#"><span class="brand-icon">✳</span><span>${t.name}<small>${t.tag}</small></span></a><nav><a href="#journal">${t.nav}</a><a href="#intention">${t.about}</a></nav><div class="header-actions"><select id="language" aria-label="${t.language}"><option value="en">English</option><option value="yue">廣東話</option><option value="zh">中文</option></select><button class="button dark" id="write">＋ ${t.add}</button></div></header>
 <main><section class="hero"><div class="hero-copy"><div class="eyebrow"><span></span>${t.eyebrow}</div><h1>${t.title}</h1><p>${t.intro}</p><a class="button dark" href="#journal">${t.browse} <span>↗</span></a><div class="hero-foot"><span class="tiny-flower">✳</span> ${t.philosophy} <span>·</span> ${t.health}</div></div><div class="hero-art" aria-hidden="true"><div class="sun"></div><div class="arch arch-one"></div><div class="arch arch-two"></div><div class="stem stem-one"></div><div class="stem stem-two"></div><div class="art-caption">THE ART OF LIVING WELL <span>01 — ∞</span></div></div></section>
 <aside class="quote"><span>“</span><div><p>${t.quote.replace(/^[“「]|[”」]$/g,'')}</p><small>${t.author}</small></div><span class="quote-star">✳</span></aside>
 <section id="journal"><div class="section-heading"><div class="eyebrow">THE JOURNAL / ${String(currentPosts().length).padStart(2,'0')}</div><h2>${t.latest}</h2><p>${t.sub}</p></div><div class="filters">${['all','philosophy','health','personal'].map(f => `<button data-filter="${f}" class="${f===filter?'active':''}" aria-pressed="${f===filter}">${t[f==='all'?'all':f]}</button>`).join('')}</div><div class="cards">${visible.map((p,i) => `<article class="card"><button class="card-open" data-read="${esc(p.id)}" aria-label="${esc(t.read+': '+p.title)}"><div class="card-art art-${p.category} pattern-${i%4}"><span class="art-circle"></span><span class="art-line"></span><span class="art-number">${p.number || '✎'}</span><span class="art-word">${p.category==='philosophy'?'REFLECT':'REST & RENEW'}</span></div><div class="card-content"><div class="card-meta"><span>${t[p.category]}</span><small>${p.own?t.personal:t.readTime}</small></div><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><div class="read">${t.read}<span>↗</span></div></div></button></article>`).join('') || `<p class="empty">${t.empty}</p>`}</div></section>
 <section class="intention" id="intention"><div class="intent-symbol">✳</div><div><div class="eyebrow">A NOTE ON THIS SPACE</div><h2>${t.intent}</h2><p>${t.intentText}</p><button class="button dark" id="write-bottom">＋ ${t.add}</button></div></section><p class="health-note">${t.note}</p></main><footer><span>${t.name} <span class="footer-dot">✳</span></span><small>${t.footer}</small><div><button id="export">${t.export}</button><button id="import">${t.import}</button><input id="file" type="file" accept="application/json,.json" hidden></div></footer><div id="status" role="status">${storageWarning?t.error:''}</div><dialog id="dialog"></dialog>`;
 document.querySelector('#language').value = lang;
 document.querySelector('#language').onchange = e => {lang=e.target.value;try {localStorage.setItem('thoughtful-language',lang);} catch {} render();};
 document.querySelectorAll('[data-filter]').forEach(b => b.onclick = () => {filter=b.dataset.filter;render();document.querySelector(`[data-filter="${filter}"]`).focus();});
 document.querySelectorAll('[data-read]').forEach(b => b.onclick = () => readPost(b.dataset.read));
 document.querySelector('#write').onclick = editor; document.querySelector('#write-bottom').onclick=editor;
 document.querySelector('#export').onclick = () => {const url=URL.createObjectURL(new Blob([JSON.stringify(posts,null,2)],{type:'application/json'})); const a=document.createElement('a');a.href=url;a.download='thoughtful-life-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 document.querySelector('#import').onclick = () => document.querySelector('#file').click();
 document.querySelector('#file').onchange = async e => {const file=e.target.files[0];if(!file)return;try {if(file.size>10000000)throw Error();const data=JSON.parse(await file.text());if(!validPosts(data))throw Error();const next=[...posts];data.forEach(p=>{if(!next.some(n=>n.id===p.id))next.push({id:p.id,title:p.title,body:p.body,lang:p.lang,category:p.category});});if(!validPosts(next))throw Error();if(persist(next)){render();document.querySelector('#status').textContent=t.imported;}} catch {alert(t.invalid);}};
}
function openDialog(html) {const d=document.querySelector('#dialog');d.innerHTML=html;d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}};}
function readPost(id) {const p=currentPosts().find(p=>p.id===id);if(!p)return;const t=copy[lang];openDialog(`<button class="dialog-close" data-close aria-label="${t.close}">×</button><div class="eyebrow">${t[p.category]}</div><h2>${esc(p.title)}</h2><div class="article-body">${p.body.split('\n\n').map(x=>`<p>${esc(x)}</p>`).join('')}</div>${p.category==='health'?`<p class="health-note">${t.note}</p>`:''}${p.own?`<button class="delete" id="delete">${t.remove}</button>`:''}`);if(p.own)document.querySelector('#delete').onclick=()=>{if(confirm(t.confirm)&&persist(posts.filter(x=>x.id!==id)))render();};}
function editor() {const t=copy[lang];openDialog(`<button class="dialog-close" data-close aria-label="${t.close}">×</button><div class="eyebrow">${t.personal}</div><h2>${t.editor}</h2><p>${t.editorSub}</p><form id="post-form"><label>${t.titleLabel}<input name="title" required maxlength="140"></label><div class="form-row"><label>${t.category}<select name="category"><option value="philosophy">${t.philosophy}</option><option value="health">${t.health}</option></select></label><label>${t.language}<select name="lang"><option value="en">English</option><option value="yue">廣東話</option><option value="zh">中文</option></select></label></div><label>${t.bodyLabel}<textarea name="body" rows="7" required maxlength="20000"></textarea></label><p class="local-note">${t.local}</p><button class="button dark" type="submit">${t.save} ↗</button></form>`);document.querySelector('[name="lang"]').value=lang;document.querySelector('#post-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=String(f.get('title')).trim(),body=String(f.get('body')).trim();if(!title||!body)return;const p={id:crypto.randomUUID(),title,body,category:String(f.get('category')),lang:String(f.get('lang'))};if(persist([p,...posts])){lang=p.lang;filter='personal';render();document.querySelector('#status').textContent=copy[lang].saved;document.querySelector('#journal').scrollIntoView({behavior:'smooth'});}};}
render();
